export const translations = {
  "en": {
    "mob-why": "The Destination", "mob-gallery": "Gallery", "mob-terrain": "Terrain", "mob-pricing": "Pricing", "mob-season": "Season", "mob-itin": "Itinerary", "mob-faq": "FAQ", "mob-about": "About", "mob-book": "Book Now", "nav-itin": "Itinerary", "nav-faq": "FAQ", "hero-from": "From", "hero-price-note": "per person &middot; 6 riding days<br>all-inclusive &middot; Catskiing / Catboarding", "gallery-label": "In Action", "gallery-title": "RAW <span>FOOTAGE</span>", "gallery2-label": "More from the Mountain", "gallery2-title": "LIFE AT <span>BASE CAMP</span>", "price-why-label": "Why is the price so fair?", "price-why-title": "FREERIDE<br>SHOULD STAY<br><span style=\"color:var(--accent);\">AFFORDABLE.</span>", "price-why-text": "<p>Catskiing has a reputation for being expensive.</p><p>One reason is the structure behind many offerings: agencies, middlemen, and multiple layers between the guest and the local operator.</p><p><strong style=\"color:var(--white);\">We work differently.</strong></p><p>Since 2018, we have worked directly with the same team on the ground &mdash; people who have been operating in this region for over 30 years. We know each other, we trust each other, and we work without detours.</p><p>That means fewer layers between you and the actual experience &mdash; and a fairer price as a result.</p><p>Add to that the lower operating costs on location compared to well-known freeride destinations like the Alps. That allows us to price fairly &mdash; without compromising on safety, organisation, or the experience on the mountain.</p><p>We believe catskiing does not have to be an exclusive luxury product. Above all, it should be one thing: a great experience in the mountains.</p>", "itin-label": "Most Popular Package", "itin-title": "Sample<br><span class=\"accent\">Itinerary</span>", "itin-sub": "Saturday to Saturday &mdash; our recommended 8-day programme in the Shar Mountains", "itin-d1n": "Day 1", "itin-d1t": "Arrival &amp; Briefing", "itin-d1i1": "Arrival in Skopje (flight times vary)", "itin-d1i2": "Transfer to the Shar Mountains &amp; hotel check-in", "itin-d1i3": "Dinner &amp; safety briefing", "itin-d1i4": "Rental equipment pick-up (avalanche pack, beacon, shovel, probe)", "itin-d1i5": "Rental snowboard or skis", "itin-d2n": "Days 2 – 6", "itin-d2t": "Full Riding Days", "itin-d2i1": "Breakfast", "itin-d2i2": "Snowcat departs — FUN begins", "itin-d2i3": "Back at the hotel", "itin-d2i4": "Relax &amp; SPA", "itin-d2i5": "Dinner", "itin-d3n": "Day 7", "itin-d3t": "Last Riding Day", "itin-d3i1": "Breakfast", "itin-d3i2": "Last riding day — make it count", "itin-d3i3": "Final run, refresh &amp; pack", "itin-d3i4": "Departure to Skopje", "itin-d3i5": "Arrival at 4★ hotel in Skopje", "itin-d3i6": "Farewell dinner", "itin-d4n": "Day 8", "itin-d4t": "Departure", "itin-d4i1": "Leisurely breakfast until 10:00", "itin-d4i2": "Hotel pick-up approx. 2.5 hours before your flight", "itin-d4i3": "Transfer to Skopje Airport — safe travels!", "itin-callout-text": "Want to stay shorter or longer? We tailor every trip individually.", "itin-callout-btn": "Book Your Trip", "form-name-label": "Name", "form-email-label": "Email", "form-city-label": "City / Country", "form-guests-label": "Number of Travellers", "form-guests-placeholder": "Select", "form-date-label": "Preferred Travel Date / Period", "form-msg-label": "Message (optional)", "form-submit-btn": "Send Enquiry", "form-note-text": "We&rsquo;ll get back to you within 24 hours.", "form-success-msg": "&#10003; &nbsp;Thank you! We&rsquo;ll be in touch within 24 hours.", "form-error-msg": "Please fill in all required fields.", "partners-label": "Proudly Supported By", "nav-why": "The Destination", "nav-terrain": "Terrain", "nav-pricing": "Pricing", "nav-season": "Season", "nav-book": "Book Now", "footer-why": "Destination", "footer-terrain": "Terrain", "footer-pricing": "Pricing", "footer-season": "Season", "footer-contact": "Contact", "hero-tag": "Catskiing &amp; Catboarding &middot; Shar Mountains &middot; North Macedonia", "hero-title": "UNTRACKED<br><span class=\"line2\">POWDER</span>", "hero-sub": "No lift queues. No mass tourism. Just untouched nature, decades of local expertise, and over 4,000 vertical meters of raw Balkan wilderness daily, waiting for your first tracks.", "hero-btn1": "See Packages", "hero-btn2": "Explore the Destination", "hero-scroll": "Scroll", "strip1": "6 Riding Days", "strip2": "Small Groups Only", "strip3": "Catskiing &amp; Catboarding from &euro;1,990", "strip4": "Flexible Dates", "strip5": "Europe&rsquo;s First Catboarding Operator", "why-label": "The Destination", "why-title": "WHY NORTH<br><span class=\"ice\">MACEDONIA</span>", "why-body": "<p>In the <strong>Shar Mountains above Popova &Scaron;apka</strong>, at 2,700 meters, our partner runs Europe&rsquo;s very first catskiing &amp; catboarding operation since the early 1990s. Over <strong>30 years of on-mountain expertise</strong>, built by a local team that knows every line, every bowl and every hidden snow pocket of these mountains, and that insider knowledge is baked into every day of your trip. RAW.MOUNTAIN has been there every season since 2018!</p><p>Not part of a ski resort. Pure backcountry. <strong>The snowcat accesses terrain no lift system ever could.</strong> From steep 50&deg; bowls to mellow tree runs. No ski resort politics. No crowded pistes. No compromises.</p><p><strong>What makes RAW.MOUNTAIN the better choice:</strong> comparable catski operators in Europe charge &euro;2,700&ndash;3,300 for just 5 days, often with larger groups and less personal service. With us you get a weekly package of <strong>6 full days of catskiing &amp; catboarding from &euro;1,990</strong>, all-inclusive, in small groups with a dedicated guide! One extra day alone is already worth the difference. The price isn&rsquo;t lower because we cut corners, it&rsquo;s lower because North Macedonia simply isn&rsquo;t Chamonix or the Arlberg.</p><p>Getting here is straightforward: the easiest connections to Skopje run via <strong>Zurich, Frankfurt or Istanbul</strong>. From many European cities, <strong>WizzAir flies direct to Skopje</strong> at very affordable prices. Once you land, we take care of everything.</p>", "stat1": "Summit Elevation", "stat2": "Vertical Meters / Day", "stat3": "Years Local Operator Experience", "stat4": "Years RAW.MOUNTAIN on the Ground", "terrain-label": "What Awaits You", "terrain-title": "CATSKIING &amp;<br><span class=\"ice\">CATBOARDING</span>", "t1h": "Steep Bowls", "t1p": "40&ndash;50&deg; sustained pitches with consistent snow coverage. The kind of line you&rsquo;ll be talking about for years. We start at the top and decide the descent based on the snow of the day.", "t2h": "Tree Runs", "t2p": "Tight, playful lines through old-growth forest. Perfect for afternoon laps when the open bowls have had enough sun. Protected from wind, always good snow.", "t3h": "Couloirs", "t3p": "Natural couloirs channeled between rock bands, from confidence-builders to committing lines. Your guide selects based on your ability and the day&rsquo;s stability.", "t4h": "Natural Features", "t4p": "Wind-sculpted gullies, pillows, and natural hits that turn every run into a creative session. No two days are the same, the mountain rearranges itself with every storm.", "t5h": "Powder Days", "t5p": "Unlike the manicured Alps, this mountain delivers genuine powder conditions throughout the season. When it storms overnight, you&rsquo;re first in line, no crowds, no tracked-out slopes.", "t6h": "The Snowcat", "t6p": "Your shuttle, your base camp, your heated refuge between runs. No lift queues, no waiting. The cat drops you at the top, you ride to the bottom, repeat. Maximum time on snow.", "pricing-label": "What&rsquo;s Included", "pricing-title": "THE PACKAGE", "price-badge": "All-Inclusive Package", "price-from": "ab / from", "price-per": "per person &middot; 6 riding days &middot; from &euro;1,990 depending on season", "price-list": "<li><span class=\"check\">&#10003;</span>6 full days of catskiing &amp; catboarding</li><li><span class=\"check\">&#10003;</span>7 nights accommodation (3-star mountain hotel + 1 night 4-star Skopje)</li><li><span class=\"check\">&#10003;</span>7&times; breakfast, 6&times; dinner at the hotel</li><li><span class=\"check\">&#10003;</span>Daily mountain lunch &amp; snacks on the cat</li><li><span class=\"check\">&#10003;</span>Airport transfers Skopje &harr; Popova &Scaron;apka</li><li><span class=\"check\">&#10003;</span>Professional guide, 30+ years local operator experience</li><li><span class=\"check\">&#10003;</span>Wax station access &ndash; your board tuned every evening</li><li><span class=\"check\">&#10003;</span>Hotel SPA access (pool, sauna)</li><li><span class=\"check\">&#10003;</span>Dinner in Skopje on departure</li><li><span class=\"check\">&#10003;</span>Full on-site logistics managed for you</li><li><span class=\"check\">&#10003;</span>Avalanche safety equipment available on request <em>(rental fee applies)</em></li><li><span class=\"check\">&#10003;</span>All national park fees included</li>", "not-incl": "<strong>Not included:</strong> Flights &middot; Alcoholic beverages at dinner &middot; Optional massages &middot; Avalanche equipment (LVS, shovel, probe, airbag, available to rent on site)", "price-cta": "Request a Spot", "cmp-title": "Why RAW.MOUNTAIN Wins on Value", "cmp-others": "Comparable Catski Operators", "cmp-sub-others": "Larger groups &middot; Less personal &middot; Premium alpine pricing", "cmp-best": "Best Value", "cmp-5days": "6 days", "cmp-6days": "6 days", "cmp-sub-ours": "Small groups &middot; Personal &middot; 30+ years local expertise", "cmp-callout": "<strong style=\"color:var(--accent)\">The math is simple:</strong> &euro;700&ndash;1,300 less per person, smaller groups, and a guide who knows this mountain inside out. We want adventure to be affordable for you!", "flex-label": "Flexible Options", "flex-list": "<li>&rarr; <strong style=\"color:var(--white)\">Individual Dates</strong>, book your own week, late December to mid-April</li><li>&rarr; <strong style=\"color:var(--white)\">Solo or Group</strong>, come alone, with friends, or as a crew</li><li>&rarr; <strong style=\"color:var(--white)\">Single Rooms</strong>, available on request (small supplement)</li><li>&rarr; <strong style=\"color:var(--white)\">Shorter Trips</strong>, 4&ndash;5 day versions available, price on request</li><li>&rarr; <strong style=\"color:var(--white)\">Mixed Ski &amp; Snowboard</strong>, catskiing and catboarding, all terrain</li>", "flights-label": "Getting to Skopje", "flights-body": "The easiest connections to Skopje run via <strong style=\"color:var(--white)\">Zurich, Frankfurt or Istanbul</strong>. From many European cities, <strong style=\"color:var(--white)\">WizzAir flies direct to Skopje</strong> at very competitive prices. For North American riders: comparable catskiing &amp; catboarding trips in Canada or Alaska start at $4,000&ndash;6,000 USD, before transatlantic flights. North Macedonia delivers world-class terrain at a fraction of the cost.", "season-label": "When To Go", "season-title": "SEASON<br><span class=\"ice\">OVERVIEW</span>", "m1": "December", "m1d": "Season opens late December. Early powder, fewer people, shorter days. Perfect for those who want the mountain entirely to themselves.", "m2": "January", "m2d": "Prime conditions. Cold temps lock in the snowpack. Deep powder frequent. Peak season for catskiing &amp; catboarding, book early.", "m3": "February", "m3d": "The sweet spot. Maximum snowpack, longer days, stable conditions. Statistically the best month for consecutive powder days.", "m4": "March", "m4d": "Unlike the Alps, fresh snowfall remains frequent well into March. Powder alerts are a regular occurrence, not a lucky bonus. Bluebird mornings, surprise storm cycles, and still-cold temps make for exceptional catskiing &amp; catboarding.", "m5": "April", "m5d": "Don&rsquo;t be fooled by the calendar. New snow hits regularly in April here, spring sun by day, fresh powder by night. Often delivers some of the best riding of the entire season. A hidden gem for late-season powder hunters.", "m6": "Custom", "m6d": "You choose the dates. We handle the rest. Individual catskiing &amp; catboarding trips available throughout the season, reach out to discuss your ideal week.", "how-label": "The Process", "how-title": "HOW IT<br><span class=\"ice\">WORKS</span>", "s1h": "Get in Touch", "s1p": "Send us your preferred dates and group size. We&rsquo;ll confirm availability and answer any questions.", "s2h": "Book Your Spot", "s2p": "Secure your place with a 20% deposit. We handle all accommodation, guide, and snowcat bookings.", "s3h": "Book Your Flight", "s3p": "Fly to Skopje via Zurich, Frankfurt or Istanbul, or direct from many European cities with WizzAir. We&rsquo;ll send routing tips once booked.", "s4h": "Arrive &amp; Ride", "s4p": "We pick you up at Skopje airport. From there, everything is taken care of. Just bring your board.", "s5h": "Best Week of Your Life", "s5p": "6 days of catskiing &amp; catboarding on untracked powder, great food, good company, and memories that don&rsquo;t fade.", "faq-label": "Got Questions?", "faq-grid": "<div class=\"faq-item\"><div class=\"faq-q\">What skill level do I need?</div><div class=\"faq-a\"><strong style=\"color:var(--accent)\">This trip is not suitable for beginners.</strong> You should be a confident, experienced winter sports enthusiast with solid off-piste experience. If you ride red and black pistes safely and have no fear of deep snow, you&rsquo;re perfectly set up, your guide always adapts the terrain to the group.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Is this only for snowboarders?</div><div class=\"faq-a\">Not at all. Both catskiing and catboarding are on offer. The terrain suits skiers and snowboarders equally, open powder country with no terrain park bias.</div></div><div class=\"faq-item\"><div class=\"faq-q\">How do I get to Skopje?</div><div class=\"faq-a\">The easiest connections run via <strong>Zurich, Frankfurt or Istanbul</strong>. From many European cities, <strong>WizzAir flies direct to Skopje</strong> at very affordable prices, check their route map for your departure city. Once you land, we take care of everything.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Do I need to bring avalanche gear?</div><div class=\"faq-a\">You don&rsquo;t need to bring your own. Avalanche safety equipment (LVS beacon, shovel, probe, and airbag backpack) is available to rent on site, please book in advance so we can reserve it for you. Your guide is avalanche-certified and makes all terrain decisions based on daily snowpack assessment.</div></div><div class=\"faq-item\"><div class=\"faq-q\">What&rsquo;s the accommodation like?</div><div class=\"faq-a\">You&rsquo;ll stay at a solid 3-star hotel at Popova &Scaron;apka with SPA access (pool, sauna), full breakfast and dinner included. The last night is at a 4-star hotel in Skopje, a great send-off before heading home.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Can I come alone?</div><div class=\"faq-a\">Absolutely. Solo travellers are very welcome. We group riders by ability and dates, so you&rsquo;ll always be catskiing or catboarding with like-minded people.</div></div><div class=\"faq-item\"><div class=\"faq-q\">What board should I bring?</div><div class=\"faq-a\">Your favourite board is the best board. A powder stick or freeride setup is ideal. A wax station is available at the hotel every evening, and we carry a spare board and binding setup just in case.</div></div><div class=\"faq-item\"><div class=\"faq-q\">What&rsquo;s the booking &amp; cancellation policy?</div><div class=\"faq-a\">A <strong>20% deposit</strong> of the total trip price secures your spot. The remaining balance is due 30 days before departure. Free cancellation up to 45 days before your trip. After that: 25% (30&ndash;45 days), 50% (29&ndash;15 days), 75% (14&ndash;7 days), 90% from 6 days before your travel date. We recommend taking out trip cancellation insurance.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Do I need travel insurance?</div><div class=\"faq-a\">Yes, strongly recommended. You&rsquo;ll need a policy that covers <strong>alpine mountain rescue and emergency rescue in alpine terrain</strong>, with a minimum coverage of &euro;10,000 for rescue costs. Most specialist winter sports insurers offer this as standard.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Is there local currency&thinsp;/&thinsp;cash needed?</div><div class=\"faq-a\">The hotel accepts credit cards, but most shops and bars in the village are cash-only. The local currency is the Macedonian Denar (MKD). ATMs are available in the area. Bring some cash for drinks and tips.</div></div>", "con-label": "Ready to Ride?", "con-title": "LET&rsquo;S MAKE<br>IT HAPPEN", "con-body": "Spots are limited and fill up fast. Whether you have questions or you&rsquo;re ready to book your catskiing &amp; catboarding week, get in touch and we&rsquo;ll sort out the details together.", "con-btn1": "Send an Email", "con-btn2": "See Full Package", "stat1d": "Your hotel sits at around 1,700m, giving you nearly 1,000 vertical meters of guaranteed fun right from the door, before the snowcat even starts climbing.", "stat2d": "4,000 vertical meters per day is guaranteed, and regularly topped. That&rsquo;s significantly more than most heliboarding or heliskiing operations can deliver.", "stat3d": "Our partner on the ground has been running catboarding since the early 1990s, true pioneers of the sport, long before it became fashionable anywhere else in Europe.", "stat4d": "Nearly a decade of personal presence on this mountain. We accompany our guests from first contact to final run. Your maximum fun is our only mission.", "trust-badge": "Europe&rsquo;s #1 Catboarding Destination", "trust-headline": "BY FAR THE BEST CHOICE FOR<br><span class=\"ice\">CATBOARDING IN EUROPE</span>", "trust-body": "We don&rsquo;t say this lightly. Over the years, RAW.MOUNTAIN has brought hundreds of riders to the Shar Mountains, skiers, snowboarders, first-timers and seasoned freeriders alike. Every single one has come home with a smile on their face and powder on their mind. This mountain, this operator, and this setup is simply in a league of its own in Europe. There is nowhere else on the continent where you get this combination of terrain quality, snowcat access, operator experience, and value, all in one place.", "ts1n": "100s", "ts1l": "Happy Riders &amp; Counting", "ts2n": "100%", "ts2l": "Would Come Back", "ts3n": "#1", "ts3l": "Catboarding Value in Europe", "trust-cta": "Secure Your Spot", "nav-about": "About", "footer-about": "About", "about-label": "The Person Behind RAW.MOUNTAIN", "about-title": "MEET<br><span class=\"ice\">FERDI</span>", "about-body": "<p>My name is Ferdi Christ and I was born in the heart of the Allg&auml;u Alps. Snowboarding has been part of my life for over 20 years &ndash; and from the very start, it was the feeling of freedom in freeride that got me hooked. Deep powder slopes, untouched lines and the feeling of absolute freedom with every single turn.</p><p>For many years I worked in the snowboard industry, exploring all kinds of mountains and freeride destinations on trips around the world. But over time, overcrowded ski resorts just became too much &ndash; I kept searching for the real, original adventure away from the mainstream. That&rsquo;s exactly why I ended up staying in North Macedonia &ndash; for me, the perfect definition of freeride. Breathtaking mountains, untouched nature, limitless possibilities, and one of the few truly affordable adventures left in the world.</p><p>With <strong>RAW.MOUNTAIN</strong> I combine my German thoroughness ;-) and professional organisation with excellent personal service and the unique Balkan vibe that you simply can&rsquo;t put into words &ndash; you have to experience it yourself.</p><p>My team and I are here for you 24/7 to give you a trip like no other &ndash; authentic, extraordinary and unforgettable.</p><p><em>I&rsquo;m looking forward to welcoming you at RAW.MOUNTAIN!</em></p><div class=\"about-signature\"><span class=\"about-sig-wave\">&#128075;</span><div><div class=\"about-sig-name\">Ferdi Christ</div><div class=\"about-sig-role\" id=\"about-sig-role\">Founder, RAW.MOUNTAIN</div></div></div>", "about-sig-role": "Founder, RAW.MOUNTAIN", "con-or": "Or reach us directly:"
  }, "de": {
    "mob-why": "Das Ziel", "mob-gallery": "Galerie", "mob-terrain": "Gelände", "mob-pricing": "Preise", "mob-season": "Saison", "mob-itin": "Ablauf", "mob-faq": "FAQ", "mob-about": "Über uns", "mob-book": "Jetzt buchen", "nav-itin": "Ablauf", "nav-faq": "FAQ", "hero-from": "Ab", "hero-price-note": "pro Person &middot; 6 Fahrtage<br>All-inclusive &middot; Catskiing / Catboarding", "gallery-label": "In Aktion", "gallery-title": "RAW <span>FOOTAGE</span>", "gallery2-label": "Mehr vom Berg", "gallery2-title": "LEBEN IM <span>BASECAMP</span>", "price-why-label": "Warum ist der Preis so fair?", "price-why-title": "FREERIDE<br>SOLLTE<br><span style=\"color:var(--accent);\">BEZAHLBAR BLEIBEN.</span>", "price-why-text": "<p>Catskiing hat den Ruf, teuer zu sein.</p><p>Ein Grund dafür ist die Struktur hinter vielen Angeboten: Agenturen, Zwischenhändler und mehrere Ebenen zwischen Gast und lokalem Anbieter.</p><p><strong style=\"color:var(--white);\">Wir arbeiten anders.</strong></p><p>Seit 2018 arbeiten wir direkt mit demselben Team vor Ort &mdash; Menschen, die seit über 30 Jahren in dieser Region tätig sind. Wir kennen uns, wir vertrauen einander und wir arbeiten ohne Umwege.</p><p>Das bedeutet weniger Ebenen zwischen dir und dem eigentlichen Erlebnis &mdash; und dadurch einen faireren Preis.</p><p>Hinzu kommen die niedrigeren Betriebskosten vor Ort im Vergleich zu bekannten Freeride-Zielen wie den Alpen. Das erlaubt uns, fair zu kalkulieren &mdash; ohne Kompromisse bei Sicherheit, Organisation oder dem Erlebnis am Berg.</p><p>Wir glauben, Catskiing muss kein exklusives Luxusprodukt sein. Vor allem sollte es eines sein: ein großartiges Erlebnis in den Bergen.</p>", "itin-label": "Beliebtestes Paket", "itin-title": "Beispiel-<br><span class=\"accent\">Ablauf</span>", "itin-sub": "Samstag bis Samstag &mdash; unser empfohlenes 8-Tage-Programm im Šar-Gebirge", "itin-d1n": "Tag 1", "itin-d1t": "Ankunft &amp; Briefing", "itin-d1i1": "Ankunft in Skopje (Flugzeiten variieren)", "itin-d1i2": "Transfer ins Šar-Gebirge &amp; Hotel-Check-in", "itin-d1i3": "Abendessen &amp; Sicherheitsbriefing", "itin-d1i4": "Abholung der Leihausrüstung (Lawinenrucksack, LVS, Schaufel, Sonde)", "itin-d1i5": "Leih-Snowboard oder -Ski", "itin-d2n": "Tag 2 – 6", "itin-d2t": "Volle Fahrtage", "itin-d2i1": "Frühstück", "itin-d2i2": "Snowcat fährt los — der FUN beginnt", "itin-d2i3": "Zurück im Hotel", "itin-d2i4": "Entspannen &amp; SPA", "itin-d2i5": "Abendessen", "itin-d3n": "Tag 7", "itin-d3t": "Letzter Fahrtag", "itin-d3i1": "Frühstück", "itin-d3i2": "Letzter Fahrtag — nutze ihn", "itin-d3i3": "Letzte Abfahrt, frisch machen &amp; packen", "itin-d3i4": "Abfahrt nach Skopje", "itin-d3i5": "Ankunft im 4★-Hotel in Skopje", "itin-d3i6": "Abschiedsessen", "itin-d4n": "Tag 8", "itin-d4t": "Abreise", "itin-d4i1": "Gemütliches Frühstück bis 10:00", "itin-d4i2": "Hotel-Abholung ca. 2,5 Stunden vor deinem Flug", "itin-d4i3": "Transfer zum Flughafen Skopje — gute Reise!", "itin-callout-text": "Kürzer oder länger bleiben? Wir gestalten jede Reise individuell.", "itin-callout-btn": "Reise buchen", "form-name-label": "Name", "form-email-label": "E-Mail", "form-city-label": "Stadt / Land", "form-guests-label": "Anzahl der Reisenden", "form-guests-placeholder": "Auswählen", "form-date-label": "Bevorzugter Reisetermin / Zeitraum", "form-msg-label": "Nachricht (optional)", "form-submit-btn": "Anfrage senden", "form-note-text": "Wir melden uns innerhalb von 24 Stunden bei dir.", "form-success-msg": "&#10003; &nbsp;Danke! Wir melden uns innerhalb von 24 Stunden.", "form-error-msg": "Bitte fülle alle Pflichtfelder aus.", "partners-label": "Stolz unterstützt von", "nav-why": "Das Ziel", "nav-terrain": "Gel&auml;nde", "nav-pricing": "Preise", "nav-season": "Saison", "nav-book": "Jetzt Buchen", "footer-why": "Ziel", "footer-terrain": "Gel&auml;nde", "footer-pricing": "Preise", "footer-season": "Saison", "footer-contact": "Kontakt", "hero-tag": "Catskiing &amp; Catboarding &middot; Shar-Gebirge &middot; Nordmazedonien", "hero-title": "UNVERSPURTER<br><span class=\"line2\">POWDER</span>", "hero-sub": "Keine Liftschlangen. Kein Massentourismus. Nur unber&uuml;hrte Natur, jahrzehntelange Ortskenntnis und &uuml;ber t&auml;glich 4.000 H&ouml;henmeter purer Balkan-Wildnis, die auf deine erste Spur warten.", "hero-btn1": "Zum Paket", "hero-btn2": "Das Ziel entdecken", "hero-scroll": "Scrollen", "strip1": "6 Fahrtage", "strip2": "Nur Kleingruppen", "strip3": "Catskiing &amp; Catboarding ab &euro;1.990", "strip4": "Flexible Termine", "strip5": "Europas erster Catboarding-Anbieter", "why-label": "Das Ziel", "why-title": "WARUM<br><span class=\"ice\">NORDMAZEDONIEN</span>", "why-body": "<p>Im <strong>Shar-Gebirge oberhalb von Popova &Scaron;apka</strong>, auf 2.700 Metern, betreibt unser Partner Europas allererste Catskiing- &amp; Catboarding Operation seit den fr&uuml;hen 90er-Jahren. &Uuml;ber <strong>30 Jahre Erfahrung vor Ort</strong>, aufgebaut von einem lokalen Team, das jede Line, jede Bowl und jeden verborgenen Schneepocket dieser Berge kennt und dieses Insiderwissen steckt in jedem Tag deines Trips. RAW.MOUNTAIN ist seit 2018 j&auml;hrlich dabei!</p><p>Kein Teil eines Skigebiets. Reines Backcountry. <strong>Die Snowcat erschlie&szlig;t Gel&auml;nde, das kein Liftsystem jemals erreichen k&ouml;nnte.</strong> Von steilen 50&deg;-Bowls bis hin zu gem&uuml;tlichen Tree-Runs. Kein Pistenbetrieb, keine Warteschlangen, keine Kompromisse.</p><p><strong>Was RAW.MOUNTAIN zur besseren Wahl macht:</strong> vergleichbare Catski-Anbieter in Europa verlangen &euro;2.700&ndash;3.300 f&uuml;r nur 5 Tage. Oft mit gr&ouml;&szlig;eren Gruppen und weniger pers&ouml;nlichem Service. Bei uns bekommst du im Wochenpaket <strong>6 volle Catskiing- &amp; Catboarding-Tage ab &euro;1.990</strong>, all-inclusive, in kleinen Gruppen mit einem Guide! Ein extra Tag allein rechtfertigt bereits den Unterschied. Der Preis ist nicht niedriger weil wir sparen, sondern weil Nordmazedonien schlicht kein Chamonix oder Arlberg ist.</p><p>Die Anreise ist einfach: Am besten erreichst du Skopje &uuml;ber <strong>Z&uuml;rich, Frankfurt oder Istanbul</strong>. Aus vielen europ&auml;ischen St&auml;dten fliegt <strong>WizzAir direkt nach Skopje</strong> zu sehr g&uuml;nstigen Preisen. Sobald du landest, k&uuml;mmern wir uns um alles.</p>", "stat1": "Gipfelh&ouml;he", "stat2": "H&ouml;henmeter / Tag", "stat3": "Jahre Betreibereerfahrung vor Ort", "stat4": "Jahre RAW.MOUNTAIN vor Ort", "terrain-label": "Was dich erwartet", "terrain-title": "CATSKIING &amp;<br><span class=\"ice\">CATBOARDING</span>", "t1h": "Steile Bowls", "t1p": "40&ndash;50&deg; steile H&auml;nge mit konstanter Schneebedeckung. Die Art von Linie, &uuml;ber die du noch Jahre sp&auml;ter redest. Wir starten oben und w&auml;hlen die Abfahrt je nach Tagesschnee.", "t2h": "Tree Runs", "t2p": "Enge, spielerische Linien durch alten Bergwald. Perfekt f&uuml;r die Nachmittagsrunde, wenn die offenen Bowls genug Sonne abbekommen haben. Windgesch&uuml;tzt, immer guter Schnee.", "t3h": "Couloirs", "t3p": "Nat&uuml;rliche Couloirs zwischen Felsformationen, von zug&auml;nglichen Einstiegslinien bis zu anspruchsvollen Steileinstiegen. Dein Guide w&auml;hlt passend zu deinem K&ouml;nnen und der Lawinensituation.", "t4h": "Natural Features", "t4p": "Windgeformte Rinnen, Pillows und nat&uuml;rliche Kicker machen jede Abfahrt zur Kreativsession. Kein Tag gleicht dem anderen, der Berg ver&auml;ndert sich mit jedem Sturm.", "t5h": "Powdertage", "t5p": "Anders als in den kultivierten Alpen liefert dieser Berg echten Powder die ganze Saison &uuml;ber. Wenn es nachts schneit, bist du als Erster dran, keine Massen, keine ausgefahrenen Hänge.", "t6h": "Der Snowcat", "t6p": "Dein Shuttle, dein Basislager, deine beheizte Zuflucht zwischen den Runs. Keine Lifts, kein Warten. Der Cat bringt dich nach oben, du f&auml;hrst runter, wiederholen. Maximale Fahrzeit.", "pricing-label": "Was enthalten ist", "pricing-title": "DAS PAKET", "price-badge": "All-Inclusive-Paket", "price-from": "ab / von", "price-per": "pro Person &middot; 6 Fahrtage &middot; ab &euro;1.990 je nach Saison", "price-list": "<li><span class=\"check\">&#10003;</span>6 volle Catskiing- &amp; Catboarding-Tage</li><li><span class=\"check\">&#10003;</span>7 N&auml;chte Unterkunft (3-Sterne-Berghotel + 1 Nacht 4-Sterne-Hotel Skopje)</li><li><span class=\"check\">&#10003;</span>7&times; Fr&uuml;hst&uuml;ck, 6&times; Abendessen im Hotel</li><li><span class=\"check\">&#10003;</span>T&auml;gliches Mittagessen &amp; Snacks am Berg</li><li><span class=\"check\">&#10003;</span>Flughafentransfer Skopje &harr; Popova &Scaron;apka</li><li><span class=\"check\">&#10003;</span>Professioneller Guide, 30+ Jahre lokale Betreiberenerfahrung</li><li><span class=\"check\">&#10003;</span>Wachstation &ndash; dein Board jeden Abend perfekt pr&auml;pariert</li><li><span class=\"check\">&#10003;</span>SPA-Bereich im Hotel (Pool, Sauna)</li><li><span class=\"check\">&#10003;</span>Dinner in Skopje bei Abreise</li><li><span class=\"check\">&#10003;</span>Vollst&auml;ndige Betreuung vor Ort</li><li><span class=\"check\">&#10003;</span>Lawinenausr&uuml;stung auf Anfrage verf&uuml;gbar <em>(Leihgeb&uuml;hr)</em></li><li><span class=\"check\">&#10003;</span>S&auml;mtliche Nationalpark-Geb&uuml;hren inbegriffen</li>", "not-incl": "<strong>Nicht enthalten:</strong> Fl&uuml;ge &middot; Alkoholische Getr&auml;nke beim Abendessen &middot; Massagen &middot; Lawinenausr&uuml;stung (LVS, Schaufel, Sonde, Rucksack, leihbar vor Ort)", "price-cta": "Platz anfragen", "cmp-title": "Warum RAW.MOUNTAIN punktet", "cmp-others": "Vergleichbare Catski-Anbieter", "cmp-sub-others": "Gr&ouml;&szlig;ere Gruppen &middot; Weniger pers&ouml;nlich &middot; Alpine Premiumpreise", "cmp-best": "Bestes Preis-Leistungs-Verh&auml;ltnis", "cmp-5days": "6 Tage", "cmp-6days": "6 Tage", "cmp-sub-ours": "Kleingruppen &middot; Pers&ouml;nlich &middot; 30+ Jahre lokale Expertise", "cmp-callout": "<strong style=\"color:var(--accent)\">Die Rechnung ist einfach:</strong> &euro;700&ndash;1.300 weniger pro Person, kleinere Gruppen und ein Guide, der diesen Berg seit Jahren kennt. Wir wollen bezahlbares Abenteuer f&uuml;r euch!", "flex-label": "Flexible Optionen", "flex-list": "<li>&rarr; <strong style=\"color:var(--white)\">Individuelle Termine</strong>, w&auml;hle deine Woche, Ende Dezember bis Mitte April</li><li>&rarr; <strong style=\"color:var(--white)\">Solo oder Gruppe</strong>, alleine, mit Freunden oder als Crew</li><li>&rarr; <strong style=\"color:var(--white)\">Einzelzimmer</strong>, auf Anfrage verf&uuml;gbar (kleiner Aufpreis)</li><li>&rarr; <strong style=\"color:var(--white)\">K&uuml;rzere Trips</strong>, 4&ndash;5 Tage m&ouml;glich, Preis auf Anfrage</li><li>&rarr; <strong style=\"color:var(--white)\">Catskiing &amp; Catboarding gemischt</strong>, Skifahrer und Snowboarder willkommen</li>", "flights-label": "Anreise nach Skopje", "flights-body": "Am einfachsten erreichst du Skopje &uuml;ber <strong style=\"color:var(--white)\">Z&uuml;rich, Frankfurt oder Istanbul</strong>. Aus vielen europ&auml;ischen St&auml;dten fliegt <strong style=\"color:var(--white)\">WizzAir direkt nach Skopje</strong> zu sehr g&uuml;nstigen Preisen. F&uuml;r Reisende aus Nordamerika: vergleichbare Catskiing- &amp; Catboarding-Trips in Kanada oder Alaska starten bei 4.000&ndash;6.000 USD, ohne Flug. Nordmazedonien bietet Weltklasse-Gel&auml;nde zu einem Bruchteil der Kosten.", "season-label": "Wann fahren?", "season-title": "SAISON<br><span class=\"ice\">&Uuml;BERBLICK</span>", "m1": "Dezember", "m1d": "Saisonstart Ende Dezember. Fr&uuml;hsaisonschnee, weniger G&auml;ste, k&uuml;rzere Tage. Ideal f&uuml;r alle, die den Berg f&uuml;r sich allein wollen.", "m2": "Januar", "m2d": "Optimale Bedingungen. Kalte Temperaturen festigen das Schneepaket. Tiefschnee h&auml;ufig. Hochsaison f&uuml;r Catskiing &amp; Catboarding, fr&uuml;h buchen.", "m3": "Februar", "m3d": "Der s&uuml;&szlig;e Punkt. Maximales Schneepaket, l&auml;ngere Tage, stabile Verh&auml;ltnisse. Statistisch bester Monat f&uuml;r aufeinanderfolgende Powdertage.", "m4": "M&auml;rz", "m4d": "Anders als in den Alpen f&auml;llt im M&auml;rz hier regelm&auml;&szlig;ig Neuschnee, Powderalarm ist keine Seltenheit, sondern Normalzustand. Bluebird-Morgen, &uuml;berraschende Sturm-Zyklen und noch kalte Temperaturen sorgen f&uuml;r au&szlig;ergew&ouml;hnliches Catskiing &amp; Catboarding.", "m5": "April", "m5d": "Lass dich nicht vom Kalender t&auml;uschen. Auch im April schneit es hier regelm&auml;&szlig;ig, tagsund&uuml;ber Sonne, nachts frischer Powder. Oft z&auml;hlen diese Tage zu den besten der ganzen Saison. Ein Geheimtipp f&uuml;r Sp&auml;tsaison-Powderjäger.", "m6": "Individuell", "m6d": "Du w&auml;hlst die Daten. Wir k&uuml;mmern uns um den Rest. Individuelle Catskiing- &amp; Catboarding-Trips sind w&auml;hrend der gesamten Saison m&ouml;glich.", "how-label": "So l&auml;uft es ab", "how-title": "WIE ES<br><span class=\"ice\">FUNKTIONIERT</span>", "s1h": "Kontakt aufnehmen", "s1p": "Schick uns deine Wunschtermine und Gruppengr&ouml;&szlig;e. Wir best&auml;tigen die Verf&uuml;gbarkeit und beantworten alle Fragen.", "s2h": "Platz sichern", "s2p": "Reserviere deinen Platz mit einer Anzahlung von 20% des Reisepreises. Wir k&uuml;mmern uns um Unterkunft, Guide und Snowcat.", "s3h": "Flug buchen", "s3p": "Flug nach Skopje &uuml;ber Z&uuml;rich, Frankfurt oder Istanbul, oder direkt aus vielen europ&auml;ischen St&auml;dten mit WizzAir. Wir geben dir nach der Buchung konkrete Routentipps.", "s4h": "Ankommen &amp; Fahren", "s4p": "Wir holen dich am Flughafen Skopje ab. Ab da ist alles organisiert. Bring einfach dein Board.", "s5h": "Beste Woche deines Lebens", "s5p": "6 Tage Catskiing &amp; Catboarding auf unverspurtem Powder, gutes Essen, tolle Menschen und Erinnerungen, die bleiben.", "faq-label": "Fragen?", "faq-grid": "<div class=\"faq-item\"><div class=\"faq-q\">Welches Fahrniveau brauche ich?</div><div class=\"faq-a\"><strong style=\"color:var(--accent)\">Dieser Trip ist nicht f&uuml;r Anf&auml;nger geeignet.</strong> Du solltest ein sicherer, erfahrener Wintersportler mit solider Off-Piste-Erfahrung sein. Wenn du rote und schwarze Pisten sicher f&auml;hrst und keine Scheu vor Tiefschnee hast, bist du bestens aufgestellt, dein Guide passt das Gel&auml;nde immer an die Gruppe an.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Ist das nur f&uuml;r Snowboarder?</div><div class=\"faq-a\">Nein. Sowohl Catskiing als auch Catboarding sind im Angebot. Das Gel&auml;nde eignet sich f&uuml;r Skifahrer und Snowboarder gleicherma&szlig;en.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Wie komme ich nach Skopje?</div><div class=\"faq-a\">Am einfachsten &uuml;ber <strong>Z&uuml;rich, Frankfurt oder Istanbul</strong>. Aus vielen europ&auml;ischen St&auml;dten fliegt <strong>WizzAir direkt nach Skopje</strong> zu sehr g&uuml;nstigen Preisen, schau auf der WizzAir-Routenkarte nach deinem Abflugort. Sobald du landest, k&uuml;mmern wir uns um alles.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Muss ich Lawinenausr&uuml;stung mitbringen?</div><div class=\"faq-a\">Du brauchst keine eigene mitzubringen. Lawinenausr&uuml;stung (LVS-Ger&auml;t, Schaufel, Sonde und Lawinenrucksack) ist vor Ort leihbar, bitte im Voraus reservieren. Dein Guide ist lawinenzertifiziert und trifft alle Gel&auml;ndeentscheidungen auf Basis der t&auml;glichen Schneebewertung.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Wie ist die Unterkunft?</div><div class=\"faq-a\">Du wohnst in einem soliden 3-Sterne-Hotel in Popova &Scaron;apka mit SPA-Zugang (Pool, Sauna), Vollpension (Fr&uuml;hst&uuml;ck und Abendessen). Die letzte Nacht verbringst du in einem 4-Sterne-Hotel in Skopje, ein guter Abschluss vor der Heimreise.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Kann ich alleine kommen?</div><div class=\"faq-a\">Absolut. Einzelreisende sind sehr willkommen. Wir stellen Gruppen nach Fahrniveau und Terminen zusammen, sodass du immer mit Gleichgesinnten f&auml;hrst.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Welches Board soll ich mitbringen?</div><div class=\"faq-a\">Dein Lieblings-Board ist das beste Board. Ein Powder- oder Freeride-Setup ist ideal. Im Hotel gibt es eine Wachstation, und wir haben ein Ersatz-Board mit Bindung dabei.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Wie sind die Buchungs- und Stornierungsbedingungen?</div><div class=\"faq-a\">Eine <strong>Anzahlung von 20%</strong> des Reisepreises sichert deinen Platz. Der Restbetrag ist 30 Tage vor Abreise f&auml;llig. Kostenlose Stornierung ist bis 45 Tage vor dem Trip m&ouml;glich. Danach werden f&auml;llig: 25% (30&ndash;45 Tage), 50% (29&ndash;15 Tage), 75% (14&ndash;7 Tage), 90% ab 6 Tage vor deinem Reisetermin. Wir empfehlen, eine Reiser&uuml;cktrittsversicherung abzuschlie&szlig;en.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Brauche ich eine Reiseversicherung?</div><div class=\"faq-a\">Ja, dringend empfohlen. Du brauchst eine Police, die <strong>alpine Bergrettung bzw. Bergrettung im alpinen Gel&auml;nde</strong> mit einer Mindestdeckung von &euro;10.000 abdeckt. Die meisten Wintersport-Spezialversicherer bieten das standardm&auml;&szlig;ig an.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Brauche ich Bargeld?</div><div class=\"faq-a\">Das Hotel akzeptiert Kreditkarten, aber die meisten L&auml;den und Bars im Ort funktionieren nur mit Bargeld. Landesw&auml;hrung ist der Mazedonische Denar (MKD). Geldautomaten sind vor Ort verf&uuml;gbar.</div></div>", "con-label": "Bereit zu fahren?", "con-title": "LOS<br>GEHT&rsquo;S", "con-body": "Pl&auml;tze sind begrenzt und schnell vergeben. Ob du Fragen hast oder direkt deine Catskiing- &amp; Catboarding-Woche buchen m&ouml;chtest, meld dich, wir kl&auml;ren alles gemeinsam.", "con-btn1": "E-Mail schreiben", "con-btn2": "Zum Paket", "stat1d": "Das Hotel liegt auf rund 1.700m, damit hast du von der T&uuml;r weg knapp 1.000 fixe H&ouml;henmeter Spa&szlig;, noch bevor der Snowcat richtig losklettern muss.", "stat2d": "4.000 H&ouml;henmeter pro Tag sind garantiert, und werden regelm&auml;&szlig;ig &uuml;bertroffen. Das ist deutlich mehr als die meisten Heli-Skiing- oder Heli-Boarding-Angebote liefern k&ouml;nnen.", "stat3d": "Unser Partner vor Ort betreibt Catboarding seit den fr&uuml;hen 90er-Jahren, echte Pionierarbeit in einer Zeit, als das Konzept in Europa noch nahezu unbekannt war.", "stat4d": "Fast ein Jahrzehnt pers&ouml;nliche Pr&auml;senz auf diesem Berg. Wir begleiten unsere G&auml;ste von der ersten Anfrage bis zum letzten Run. Dein maximaler Spa&szlig; ist unsere einzige Mission.", "trust-badge": "Europas Nr. 1 Catboarding-Destination", "trust-headline": "MIT ABSTAND DIE BESTE WAHL F&Uuml;R<br><span class=\"ice\">CATBOARDING IN EUROPA</span>", "trust-body": "Das sagen wir nicht leichtfertig. RAW.MOUNTAIN hat &uuml;ber die Jahre hunderte Rider ins Shar-Gebirge gebracht, Skifahrer, Snowboarder, Einsteiger und erfahrene Freerider gleicherma&szlig;en. Jeder einzelne ist mit einem L&auml;cheln im Gesicht und Powder im Kopf nach Hause gekommen. Dieser Berg, dieser Betreiber und dieses Setup sind in Europa schlicht in einer eigenen Liga. Es gibt keinen anderen Ort auf dem Kontinent, der diese Kombination aus Gel&auml;ndequalit&auml;t, Snowcat-Zugang, Betreibererfahrung und Preis-Leistung bietet, alles an einem Ort.", "ts1n": "100+", "ts1l": "Gl&uuml;ckliche Rider &amp; mehr", "ts2n": "100%", "ts2l": "W&uuml;rden wiederkommen", "ts3n": "#1", "ts3l": "Catboarding-Preis-Leistung in Europa", "trust-cta": "Jetzt Platz sichern", "nav-about": "&Uuml;ber mich", "footer-about": "&Uuml;ber mich", "about-label": "Der Mensch hinter RAW.MOUNTAIN", "about-title": "HALLO,<br><span class=\"ice\">ICH BIN FERDI</span>", "about-body": "<p>Mein Name ist Ferdi Christ und ich bin mitten in den Allg&auml;uer Alpen geboren. Seit &uuml;ber 20 Jahren begleitet mich das Snowboarden durchs Leben &ndash; und von Anfang an war es vor allem das Freiheitsgef&uuml;hl des Freeridens, das mich begeistert hat. Tief verschneite Powderh&auml;nge, unber&uuml;hrte Lines und das Gef&uuml;hl, bei jedem Turn absolute Freiheit zu sp&uuml;ren.</p><p>&Uuml;ber viele Jahre war ich in der Snowboard-Industrie t&auml;tig und habe auf zahlreichen Trips rund um die Welt die unterschiedlichsten Berge und Freeride-Destinationen erlebt. Mit der Zeit wurden mir &uuml;berf&uuml;llte Skigebiete jedoch einfach zu viel, denn ich suchte weiterhin nach dem echten, urspr&uuml;nglichen Abenteuer abseits des Mainstreams. Genau deshalb bin ich in Nordmazedonien h&auml;ngen geblieben &ndash; f&uuml;r mich der perfekte Inbegriff von Freeriden. Atemberaubende Berge, unber&uuml;hrte Natur, grenzenlose M&ouml;glichkeiten und dazu eines der wenigen noch wirklich bezahlbaren Abenteuer dieser Welt.</p><p>Mit <strong>RAW.MOUNTAIN</strong> verbinde ich meine deutsche Genauigkeit ;-) und professionelle Organisation mit exzellenter Betreuung und dem einzigartigen Balkan-Vibe, den man nicht erz&auml;hlen kann &ndash; man muss ihn selbst erleben.</p><p>Mein Team und ich stehen euch 24/7 mit Rat und Tat zur Seite, um euch einen Trip der besonderen Art zu bieten &ndash; authentisch, au&szlig;ergew&ouml;hnlich und unvergesslich.</p><p><em>Ich freue mich darauf, euch bei RAW.MOUNTAIN willkommen zu hei&szlig;en!</em></p><div class=\"about-signature\"><span class=\"about-sig-wave\">&#128075;</span><div><div class=\"about-sig-name\">Ferdi Christ</div><div class=\"about-sig-role\">Gr&uuml;nder, RAW.MOUNTAIN</div></div></div>", "about-sig-role": "Gr&uuml;nder, RAW.MOUNTAIN", "con-or": "Oder direkt erreichen:"
  }, "es": {
    "mob-why": "El Destino", "mob-gallery": "Galería", "mob-terrain": "Terreno", "mob-pricing": "Precios", "mob-season": "Temporada", "mob-itin": "Itinerario", "mob-faq": "FAQ", "mob-about": "Acerca de", "mob-book": "Reservar", "nav-itin": "Itinerario", "nav-faq": "FAQ", "hero-from": "Desde", "hero-price-note": "por persona &middot; 6 días de esquí<br>todo incluido &middot; Catskiing / Catboarding", "gallery-label": "En Acción", "gallery-title": "RAW <span>FOOTAGE</span>", "gallery2-label": "Más de la Montaña", "gallery2-title": "VIDA EN EL <span>CAMPAMENTO</span>", "price-why-label": "¿Por qué el precio es tan justo?", "price-why-title": "EL FREERIDE<br>DEBE SEGUIR<br><span style=\"color:var(--accent);\">SIENDO ASEQUIBLE.</span>", "price-why-text": "<p>El catskiing tiene fama de ser caro.</p><p>Una razón es la estructura detrás de muchas ofertas: agencias, intermediarios y múltiples niveles entre el huésped y el operador local.</p><p><strong style=\"color:var(--white);\">Nosotros trabajamos de otra manera.</strong></p><p>Desde 2018 trabajamos directamente con el mismo equipo sobre el terreno &mdash; personas que llevan más de 30 años operando en esta región. Nos conocemos, confiamos los unos en los otros y trabajamos sin rodeos.</p><p>Eso significa menos niveles entre ti y la experiencia real &mdash; y, como resultado, un precio más justo.</p><p>A ello se suman los menores costes operativos en el lugar en comparación con destinos freeride conocidos como los Alpes. Eso nos permite poner un precio justo &mdash; sin renunciar a la seguridad, la organización o la experiencia en la montaña.</p><p>Creemos que el catskiing no tiene por qué ser un producto de lujo exclusivo. Ante todo, debe ser una cosa: una gran experiencia en la montaña.</p>", "itin-label": "Paquete Más Popular", "itin-title": "Itinerario<br><span class=\"accent\">de Ejemplo</span>", "itin-sub": "De sábado a sábado &mdash; nuestro programa recomendado de 8 días en las montañas Šar", "itin-d1n": "Día 1", "itin-d1t": "Llegada &amp; Briefing", "itin-d1i1": "Llegada a Skopie (los horarios de vuelo varían)", "itin-d1i2": "Traslado a las montañas Šar &amp; check-in en el hotel", "itin-d1i3": "Cena &amp; briefing de seguridad", "itin-d1i4": "Recogida del equipo de alquiler (mochila antiavalancha, ARVA, pala, sonda)", "itin-d1i5": "Snowboard o esquís de alquiler", "itin-d2n": "Días 2 – 6", "itin-d2t": "Días Completos de Esquí", "itin-d2i1": "Desayuno", "itin-d2i2": "El snowcat sale — empieza la DIVERSIÓN", "itin-d2i3": "De vuelta al hotel", "itin-d2i4": "Relax &amp; SPA", "itin-d2i5": "Cena", "itin-d3n": "Día 7", "itin-d3t": "Último Día de Esquí", "itin-d3i1": "Desayuno", "itin-d3i2": "Último día de esquí — aprovéchalo", "itin-d3i3": "Última bajada, refrescarse &amp; hacer las maletas", "itin-d3i4": "Salida hacia Skopie", "itin-d3i5": "Llegada al hotel 4★ en Skopie", "itin-d3i6": "Cena de despedida", "itin-d4n": "Día 8", "itin-d4t": "Salida", "itin-d4i1": "Desayuno tranquilo hasta las 10:00", "itin-d4i2": "Recogida en el hotel aprox. 2,5 horas antes de tu vuelo", "itin-d4i3": "Traslado al aeropuerto de Skopie — ¡buen viaje!", "itin-callout-text": "¿Quieres quedarte menos o más tiempo? Adaptamos cada viaje de forma individual.", "itin-callout-btn": "Reserva Tu Viaje", "form-name-label": "Nombre", "form-email-label": "Correo electrónico", "form-city-label": "Ciudad / País", "form-guests-label": "Número de Viajeros", "form-guests-placeholder": "Seleccionar", "form-date-label": "Fecha / Período de Viaje Preferido", "form-msg-label": "Mensaje (opcional)", "form-submit-btn": "Enviar Consulta", "form-note-text": "Te responderemos en un plazo de 24 horas.", "form-success-msg": "&#10003; &nbsp;¡Gracias! Nos pondremos en contacto en un plazo de 24 horas.", "form-error-msg": "Por favor, completa todos los campos obligatorios.", "partners-label": "Con el Orgulloso Apoyo De", "nav-why": "El Destino", "nav-terrain": "Terreno", "nav-pricing": "Precios", "nav-season": "Temporada", "nav-book": "Reservar Ahora", "footer-why": "Destino", "footer-terrain": "Terreno", "footer-pricing": "Precios", "footer-season": "Temporada", "footer-contact": "Contacto", "hero-tag": "Catskiing &amp; Catboarding &middot; Monta&ntilde;as &Scaron;ar &middot; Macedonia del Norte", "hero-title": "NIEVE<br><span class=\"line2\">VIRGEN</span>", "hero-sub": "Sin colas en remontes. Sin turismo masivo. Solo naturaleza virgen, d&eacute;cadas de conocimiento local y m&aacute;s de 4.000 metros verticales de Balkan salvaje al d&iacute;a, esperando tu primera huella.", "hero-btn1": "Ver Paquetes", "hero-btn2": "Explorar el Destino", "hero-scroll": "Deslizar", "strip1": "6 D&iacute;as de Esqu&iacute;", "strip2": "Solo Grupos Peque&ntilde;os", "strip3": "Catskiing &amp; Catboarding desde &euro;1.990", "strip4": "Fechas Flexibles", "strip5": "El Primer Operador de Catboarding de Europa", "why-label": "El Destino", "why-title": "&iquest;POR QU&Eacute;<br><span class=\"ice\">MACEDONIA DEL NORTE</span>?", "why-body": "<p>En las <strong>Monta&ntilde;as &Scaron;ar sobre Popova &Scaron;apka</strong>, a 2.700 metros de altitud, nuestro socio opera la primera operaci&oacute;n de catskiing &amp; catboarding de Europa desde principios de los a&ntilde;os 90. M&aacute;s de <strong>30 a&ntilde;os de experiencia local</strong>, acumulados por un equipo que conoce cada l&iacute;nea, cada cuenco y cada bolsillo de nieve de estas monta&ntilde;as, y ese conocimiento interno est&aacute; presente en cada d&iacute;a de tu viaje. &iexcl;RAW.MOUNTAIN lleva all&iacute; cada temporada desde 2018!</p><p>No forma parte de una estaci&oacute;n de esqu&iacute;. Backcountry puro. <strong>La snowcat accede a terrenos imposibles para cualquier sistema de remontes.</strong> Desde cuencos de 50&deg; hasta tranquilas bajadas entre &aacute;rboles. Sin aglomeraciones, sin pistas preparadas, sin compromisos.</p><p><strong>Por qu&eacute; RAW.MOUNTAIN es la mejor elecci&oacute;n:</strong> los operadores comparables en Europa cobran &euro;2.700&ndash;3.300 por solo 5 d&iacute;as, a menudo con grupos m&aacute;s grandes y menos servicio personal. Con nosotros obtienes en el paquete semanal <strong>6 d&iacute;as completos de catskiing &amp; catboarding desde &euro;1.990</strong>, todo incluido, en grupos peque&ntilde;os con un gu&iacute;a dedicado! Un d&iacute;a extra ya justifica la diferencia. El precio no es menor porque recortemos, sino porque Macedonia del Norte simplemente no es Chamonix ni el Arlberg.</p><p>Llegar es sencillo: las conexiones m&aacute;s f&aacute;ciles a Skopje pasan por <strong>Z&uacute;rich, Frankfurt o Estambul</strong>. Desde muchas ciudades europeas, <strong>WizzAir vuela directo a Skopje</strong> a precios muy asequibles. Una vez que aterrizas, nos encargamos de todo.</p>", "stat1": "Altitud Cumbre", "stat2": "Metros Verticales / D&iacute;a", "stat3": "A&ntilde;os de Experiencia del Operador", "stat4": "A&ntilde;os RAW.MOUNTAIN in situ", "terrain-label": "Lo que te espera", "terrain-title": "CATSKIING &amp;<br><span class=\"ice\">CATBOARDING</span>", "t1h": "Cuencos Pronunciados", "t1p": "Pendientes sostenidas de 40&ndash;50&deg; con cobertura de nieve consistente. El tipo de l&iacute;nea del que hablar&aacute;s durante a&ntilde;os. Decidimos la bajada seg&uacute;n la nieve del d&iacute;a.", "t2h": "Bajadas entre &Aacute;rboles", "t2p": "L&iacute;neas estrechas y juguetonas a trav&eacute;s de bosque antiguo. Perfectas para las vueltas de tarde. Protegidas del viento, nieve siempre buena.", "t3h": "Couloirs", "t3p": "Couloirs naturales entre formaciones rocosas, desde l&iacute;neas accesibles hasta opciones comprometidas. Tu gu&iacute;a elige seg&uacute;n tu nivel y la estabilidad del d&iacute;a.", "t4h": "Estructuras Naturales", "t4p": "Barrancos moldeados por el viento, pillows y kickers naturales que convierten cada bajada en una sesi&oacute;n creativa. No hay dos d&iacute;as iguales, la monta&ntilde;a se reorganiza con cada tormenta.", "t5h": "D&iacute;as de Polvo", "t5p": "A diferencia de los Alpes, esta monta&ntilde;a ofrece condiciones de polvo genuinas durante toda la temporada. Cuando nieva de noche, t&uacute; eres el primero, sin multitudes, sin pistas batidas.", "t6h": "El Snowcat", "t6p": "Tu transporte, tu campo base, tu refugio calefactado entre bajadas. Sin colas, sin esperas. El cat te sube arriba, t&uacute; bajas, repites. M&aacute;ximo tiempo sobre la nieve.", "pricing-label": "Qu&eacute; Est&aacute; Incluido", "pricing-title": "EL PAQUETE", "price-badge": "Paquete Todo Incluido", "price-from": "desde", "price-per": "por persona &middot; 6 d&iacute;as &middot; desde &euro;1.990 seg&uacute;n temporada", "price-list": "<li><span class=\"check\">&#10003;</span>6 d&iacute;as completos de catskiing &amp; catboarding</li><li><span class=\"check\">&#10003;</span>7 noches de alojamiento (hotel de monta&ntilde;a 3 estrellas + 1 noche hotel 4 estrellas Skopje)</li><li><span class=\"check\">&#10003;</span>7&times; desayuno, 6&times; cena en el hotel</li><li><span class=\"check\">&#10003;</span>Almuerzo diario y snacks en el snowcat</li><li><span class=\"check\">&#10003;</span>Transfers aeropuerto Skopje &harr; Popova &Scaron;apka</li><li><span class=\"check\">&#10003;</span>Gu&iacute;a profesional, 30+ a&ntilde;os de experiencia local del operador</li><li><span class=\"check\">&#10003;</span>Acceso a la estaci&oacute;n de cera &ndash; tabla preparada cada noche</li><li><span class=\"check\">&#10003;</span>Acceso al SPA del hotel (piscina, sauna)</li><li><span class=\"check\">&#10003;</span>Cena en Skopje a la salida</li><li><span class=\"check\">&#10003;</span>Log&iacute;stica in situ completamente gestionada</li><li><span class=\"check\">&#10003;</span>Equipo de avalanchas disponible bajo petici&oacute;n <em>(tarifa de alquiler)</em></li><li><span class=\"check\">&#10003;</span>Todas las tasas del parque nacional incluidas</li>", "not-incl": "<strong>No incluido:</strong> Vuelos &middot; Bebidas alcoh&oacute;licas en la cena &middot; Masajes opcionales &middot; Equipo de avalanchas (LVS, pala, sonda, airbag, disponible en alquiler)", "price-cta": "Solicitar Plaza", "cmp-title": "Por qu&eacute; RAW.MOUNTAIN gana en valor", "cmp-others": "Operadores Catski Comparables", "cmp-sub-others": "Grupos m&aacute;s grandes &middot; Menos personal &middot; Precios alpinos premium", "cmp-best": "Mejor Precio", "cmp-5days": "6 d&iacute;as", "cmp-6days": "6 d&iacute;as", "cmp-sub-ours": "Grupos peque&ntilde;os &middot; Personal &middot; 30+ a&ntilde;os de expertise local", "cmp-callout": "<strong style=\"color:var(--accent)\">La matem&aacute;tica es sencilla:</strong> &euro;700&ndash;1.300 menos por persona, grupos m&aacute;s peque&ntilde;os y un gu&iacute;a que conoce esta monta&ntilde;a a fondo. &iexcl;Queremos que la aventura sea asequible para vosotros!", "flex-label": "Opciones Flexibles", "flex-list": "<li>&rarr; <strong style=\"color:var(--white)\">Fechas Individuales</strong>, elige tu semana, finales de diciembre a mediados de abril</li><li>&rarr; <strong style=\"color:var(--white)\">Solo o en Grupo</strong>, ven solo, con amigos o como equipo</li><li>&rarr; <strong style=\"color:var(--white)\">Habitaci&oacute;n Individual</strong>, disponible bajo petici&oacute;n (peque&ntilde;o suplemento)</li><li>&rarr; <strong style=\"color:var(--white)\">Viajes M&aacute;s Cortos</strong>, versiones de 4&ndash;5 d&iacute;as disponibles, precio bajo petici&oacute;n</li><li>&rarr; <strong style=\"color:var(--white)\">Catskiing &amp; Catboarding Mixto</strong>, esquiadores y snowboarders bienvenidos</li>", "flights-label": "C&oacute;mo llegar a Skopje", "flights-body": "Las conexiones m&aacute;s f&aacute;ciles a Skopje pasan por <strong style=\"color:var(--white)\">Z&uacute;rich, Frankfurt o Estambul</strong>. Desde muchas ciudades europeas, <strong style=\"color:var(--white)\">WizzAir vuela directo a Skopje</strong> a precios muy competitivos. Para riders norteamericanos: viajes de catskiing &amp; catboarding comparables en Canad&aacute; o Alaska parten de 4.000&ndash;6.000 USD, antes de los vuelos transatl&aacute;nticos. Macedonia del Norte ofrece terreno de primer nivel a una fracci&oacute;n del coste.", "season-label": "Cu&aacute;ndo Ir", "season-title": "TEMPORADA<br><span class=\"ice\">GENERAL</span>", "m1": "Diciembre", "m1d": "La temporada abre a finales de diciembre. Nieve de principio de temporada, menos gente, d&iacute;as m&aacute;s cortos. Perfecto para los que quieren la monta&ntilde;a para ellos solos.", "m2": "Enero", "m2d": "Condiciones &oacute;ptimas. Las bajas temperaturas consolidan el manto nivoso. Polvo frecuente. Temporada alta de catskiing &amp; catboarding, reserva con anticipaci&oacute;n.", "m3": "Febrero", "m3d": "El punto dulce. Manto de nieve m&aacute;ximo, d&iacute;as m&aacute;s largos, condiciones estables. Estad&iacute;sticamente el mejor mes para d&iacute;as de polvo consecutivos.", "m4": "Marzo", "m4d": "A diferencia de los Alpes, las nevadas frescas son habituales bien entrado marzo, las alertas de polvo son frecuentes, no una excepci&oacute;n. Ma&ntilde;anas azules, ciclos de tormenta sorpresa y temperaturas a&uacute;n fr&iacute;as hacen del catskiing &amp; catboarding algo excepcional.", "m5": "Abril", "m5d": "No te enga&ntilde;e el calendario. La nieve fresca sigue cayendo regularmente en abril, sol de primavera de d&iacute;a, polvo fresco de noche. A menudo, los mejores d&iacute;as de toda la temporada. Un secreto para cazadores de polvo de temporada tard&iacute;a.", "m6": "Personalizado", "m6d": "T&uacute; eliges las fechas. Nosotros nos encargamos del resto. Viajes de catskiing &amp; catboarding disponibles toda la temporada.", "how-label": "El Proceso", "how-title": "C&Oacute;MO<br><span class=\"ice\">FUNCIONA</span>", "s1h": "Cont&aacute;ctanos", "s1p": "Env&iacute;anos tus fechas preferidas y el tama&ntilde;o del grupo. Confirmaremos disponibilidad y responderemos todas tus preguntas.", "s2h": "Reserva tu Plaza", "s2p": "Asegura tu lugar con un dep&oacute;sito del 20% del precio. Nos encargamos de todo: alojamiento, gu&iacute;a y snowcat.", "s3h": "Reserva tu Vuelo", "s3p": "Vuela a Skopje v&iacute;a Z&uacute;rich, Frankfurt o Estambul, o directo desde muchas ciudades europeas con WizzAir. Te enviaremos consejos de ruta una vez reservado.", "s4h": "Llega y Esqu&iacute;a", "s4p": "Te recogemos en el aeropuerto de Skopje. Desde ese momento, todo est&aacute; organizado. Solo trae tu tabla.", "s5h": "La Mejor Semana de tu Vida", "s5p": "6 d&iacute;as de catskiing &amp; catboarding en nieve virgen, buena comida, buena compa&ntilde;&iacute;a y recuerdos que no se desvanecen.", "faq-label": "&iquest;Tienes Preguntas?", "faq-grid": "<div class=\"faq-item\"><div class=\"faq-q\">&iquest;Qu&eacute; nivel necesito?</div><div class=\"faq-a\"><strong style=\"color:var(--accent)\">Este viaje no es apto para principiantes.</strong> Debes ser un deportista de invierno experimentado con s&oacute;lida experiencia fuera de pista. Si dominas las pistas rojas y negras con seguridad y no te asusta la nieve profunda, est&aacute;s perfectamente preparado, tu gu&iacute;a siempre adaptar&aacute; el terreno al grupo.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;Es solo para snowboarders?</div><div class=\"faq-a\">Para nada. Tanto el catskiing como el catboarding est&aacute;n disponibles. El terreno se adapta perfectamente a esquiadores y snowboarders.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;C&oacute;mo llego a Skopje?</div><div class=\"faq-a\">Las conexiones m&aacute;s f&aacute;ciles pasan por <strong>Z&uacute;rich, Frankfurt o Estambul</strong>. Desde muchas ciudades europeas, <strong>WizzAir vuela directo a Skopje</strong> a precios muy asequibles. Una vez que aterrizas, nos encargamos de todo.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;Necesito traer equipo de avalanchas?</div><div class=\"faq-a\">No necesitas traer el tuyo. El equipo de avalanchas (baliza LVS, pala, sonda y mochila airbag) est&aacute; disponible en alquiler in situ, reserva con antelaci&oacute;n. Tu gu&iacute;a est&aacute; certificado y toma todas las decisiones de terreno.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;C&oacute;mo es el alojamiento?</div><div class=\"faq-a\">Te hospedar&aacute;s en un s&oacute;lido hotel de 3 estrellas en Popova &Scaron;apka con acceso al SPA, desayuno y cena incluidos. La &uacute;ltima noche es en un hotel de 4 estrellas en Skopje.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;Puedo venir solo?</div><div class=\"faq-a\">Por supuesto. Los viajeros solos son muy bienvenidos. Formamos grupos seg&uacute;n el nivel y las fechas, por lo que siempre rodar&aacute;s con gente afin.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;Qu&eacute; tabla debo traer?</div><div class=\"faq-a\">Tu tabla favorita es la mejor. Un setup de powder o freeride es ideal. Hay una estaci&oacute;n de cera en el hotel cada noche, y llevamos tabla y fijaciones de repuesto por si acaso.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;Cu&aacute;l es la pol&iacute;tica de reserva y cancelaci&oacute;n?</div><div class=\"faq-a\">Un <strong>dep&oacute;sito del 20%</strong> del precio total asegura tu plaza. El importe restante vence 30 d&iacute;as antes de la salida. Cancelaci&oacute;n gratuita hasta 45 d&iacute;as antes de tu viaje. Despu&eacute;s: 25% (30&ndash;45 d&iacute;as), 50% (29&ndash;15 d&iacute;as), 75% (14&ndash;7 d&iacute;as), 90% a partir de 6 d&iacute;as antes de tu fecha de viaje. Recomendamos contratar un seguro de cancelaci&oacute;n de viaje.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;Necesito seguro de viaje?</div><div class=\"faq-a\">S&iacute;, muy recomendado. Necesitas una p&oacute;liza que cubra <strong>el rescate de monta&ntilde;a alpino y operaciones de rescate en terreno alpino</strong>, con una cobertura m&iacute;nima de &euro;10.000. La mayor&iacute;a de aseguradoras de deportes de invierno lo ofrecen de serie.</div></div><div class=\"faq-item\"><div class=\"faq-q\">&iquest;Necesito llevar dinero en efectivo?</div><div class=\"faq-a\">El hotel acepta tarjetas, pero la mayor&iacute;a de tiendas y bares del pueblo son solo efectivo. La moneda local es el Denar macedonio (MKD). Hay cajeros disponibles en la zona.</div></div>", "con-label": "&iquest;Listo para Esquiar?", "con-title": "HAG&Aacute;MOSLO<br>REALIDAD", "con-body": "Las plazas son limitadas y se agotan r&aacute;pido. Tanto si tienes preguntas como si est&aacute;s listo para reservar tu semana de catskiing &amp; catboarding, cont&aacute;ctanos y organizamos todo juntos.", "con-btn1": "Enviar un Email", "con-btn2": "Ver Paquete Completo", "stat1d": "Tu hotel se encuentra a unos 1.700m, lo que te da casi 1.000 metros verticales de diversi&oacute;n garantizada desde la puerta, antes de que el snowcat empiece a subir.", "stat2d": "4.000 metros verticales al d&iacute;a est&aacute;n garantizados, y se superan habitualmente. Eso es significativamente m&aacute;s de lo que la mayor&iacute;a de operaciones de heli-ski o heli-boarding pueden ofrecer.", "stat3d": "Nuestro socio local lleva gestionando el catboarding desde principios de los a&ntilde;os 90, auténticos pioneros del deporte, mucho antes de que se pusiera de moda en cualquier otro lugar de Europa.", "stat4d": "Casi una d&eacute;cada de presencia personal en esta monta&ntilde;a. Acompa&ntilde;amos a nuestros hu&eacute;spedes desde el primer contacto hasta el &uacute;ltimo descenso. Tu diversi&oacute;n m&aacute;xima es nuestra &uacute;nica misi&oacute;n.", "trust-badge": "El Destino de Catboarding N&uacute;mero 1 de Europa", "trust-headline": "CON DIFERENCIA LA MEJOR ELECCI&Oacute;N PARA<br><span class=\"ice\">CATBOARDING EN EUROPA</span>", "trust-body": "No lo decimos a la ligera. A lo largo de los a&ntilde;os, RAW.MOUNTAIN ha llevado a cientos de riders a las Monta&ntilde;as &Scaron;ar, esquiadores, snowboarders, principiantes y freeriders experimentados por igual. Cada uno de ellos ha vuelto a casa con una sonrisa en la cara y el polvo en la mente. Esta monta&ntilde;a, este operador y esta propuesta est&aacute;n sencillamente en una liga propia en Europa. No hay ning&uacute;n otro lugar en el continente que ofrezca esta combinaci&oacute;n de calidad del terreno, acceso en snowcat, experiencia del operador y valor, todo en un mismo lugar.", "ts1n": "100+", "ts1l": "Riders Felices y Contando", "ts2n": "100%", "ts2l": "Volver&iacute;an a Venir", "ts3n": "#1", "ts3l": "Mejor Valor de Catboarding en Europa", "trust-cta": "Asegura tu Plaza", "nav-about": "Sobre M&iacute;", "footer-about": "Sobre m&iacute;", "about-label": "La Persona detr&aacute;s de RAW.MOUNTAIN", "about-title": "HOLA,<br><span class=\"ice\">SOY FERDI</span>", "about-body": "<p>Me llamo Ferdi Christ y nac&iacute; en el coraz&oacute;n de los Alpes de Allg&auml;u. El snowboard lleva m&aacute;s de 20 a&ntilde;os acompa&ntilde;&aacute;ndome en la vida &ndash; y desde el principio fue sobre todo la sensaci&oacute;n de libertad del freeride lo que me apasion&oacute;. Laderas de polvo profundo, l&iacute;neas v&iacute;rgenes y esa sensaci&oacute;n de libertad absoluta en cada giro.</p><p>Durante muchos a&ntilde;os trabaj&eacute; en la industria del snowboard y viv&iacute; las m&aacute;s diversas monta&ntilde;as y destinos de freeride en viajes por todo el mundo. Sin embargo, con el tiempo las estaciones masificadas se me hicieron demasiado &ndash; segu&iacute;a buscando la aventura auténtica y original alejada del turismo de masas. Por eso me qued&eacute; en Macedonia del Norte &ndash; para m&iacute;, la definici&oacute;n perfecta del freeride. Monta&ntilde;as impresionantes, naturaleza virgen, posibilidades infinitas y una de las pocas aventuras verdaderamente asequibles que quedan en el mundo.</p><p>Con <strong>RAW.MOUNTAIN</strong> combino mi precisi&oacute;n alemana ;-) y organizaci&oacute;n profesional con un servicio excelente y el &uacute;nico ambiente balc&aacute;nico que no se puede describir &ndash; hay que vivirlo uno mismo.</p><p>Mi equipo y yo estamos a vuestra disposici&oacute;n 24/7 para ofreceros un viaje &uacute;nico &ndash; aut&eacute;ntico, extraordinario e inolvidable.</p><p><em>&iexcl;Estoy deseando daros la bienvenida en RAW.MOUNTAIN!</em></p><div class=\"about-signature\"><span class=\"about-sig-wave\">&#128075;</span><div><div class=\"about-sig-name\">Ferdi Christ</div><div class=\"about-sig-role\">Fundador, RAW.MOUNTAIN</div></div></div>", "about-sig-role": "Fundador, RAW.MOUNTAIN", "con-or": "O cont&aacute;ctanos directamente:"
  }, "nl": {
    "mob-why": "De Bestemming", "mob-gallery": "Galerij", "mob-terrain": "Terrein", "mob-pricing": "Prijzen", "mob-season": "Seizoen", "mob-itin": "Programma", "mob-faq": "FAQ", "mob-about": "Over ons", "mob-book": "Nu boeken", "nav-itin": "Programma", "nav-faq": "FAQ", "hero-from": "Vanaf", "hero-price-note": "per persoon &middot; 6 rijdagen<br>all-inclusive &middot; Catskiing / Catboarding", "gallery-label": "In Actie", "gallery-title": "RAW <span>FOOTAGE</span>", "gallery2-label": "Meer van de Berg", "gallery2-title": "LEVEN OP <span>BASECAMP</span>", "price-why-label": "Waarom is de prijs zo eerlijk?", "price-why-title": "FREERIDE<br>MOET<br><span style=\"color:var(--accent);\">BETAALBAAR BLIJVEN.</span>", "price-why-text": "<p>Catskiing heeft de reputatie duur te zijn.</p><p>Een reden is de structuur achter veel aanbiedingen: bureaus, tussenpersonen en meerdere lagen tussen de gast en de lokale operator.</p><p><strong style=\"color:var(--white);\">Wij werken anders.</strong></p><p>Sinds 2018 werken we rechtstreeks samen met hetzelfde team ter plaatse &mdash; mensen die al meer dan 30 jaar in deze regio actief zijn. We kennen elkaar, we vertrouwen elkaar en we werken zonder omwegen.</p><p>Dat betekent minder lagen tussen jou en de echte ervaring &mdash; en daardoor een eerlijkere prijs.</p><p>Daar komen de lagere operationele kosten ter plaatse bij, vergeleken met bekende freeride-bestemmingen zoals de Alpen. Daardoor kunnen we eerlijk prijzen &mdash; zonder concessies aan veiligheid, organisatie of de ervaring op de berg.</p><p>Wij geloven dat catskiing geen exclusief luxeproduct hoeft te zijn. Bovenal moet het één ding zijn: een geweldige ervaring in de bergen.</p>", "itin-label": "Populairste Pakket", "itin-title": "Voorbeeld-<br><span class=\"accent\">Programma</span>", "itin-sub": "Zaterdag tot zaterdag &mdash; ons aanbevolen 8-daagse programma in het Šar-gebergte", "itin-d1n": "Dag 1", "itin-d1t": "Aankomst &amp; Briefing", "itin-d1i1": "Aankomst in Skopje (vluchttijden variëren)", "itin-d1i2": "Transfer naar het Šar-gebergte &amp; hotel check-in", "itin-d1i3": "Diner &amp; veiligheidsbriefing", "itin-d1i4": "Ophalen huuruitrusting (lawinerugzak, transceiver, schep, sonde)", "itin-d1i5": "Huursnowboard of -ski's", "itin-d2n": "Dag 2 – 6", "itin-d2t": "Volledige Rijdagen", "itin-d2i1": "Ontbijt", "itin-d2i2": "Snowcat vertrekt — de FUN begint", "itin-d2i3": "Terug in het hotel", "itin-d2i4": "Ontspannen &amp; SPA", "itin-d2i5": "Diner", "itin-d3n": "Dag 7", "itin-d3t": "Laatste Rijdag", "itin-d3i1": "Ontbijt", "itin-d3i2": "Laatste rijdag — maak er werk van", "itin-d3i3": "Laatste afdaling, opfrissen &amp; inpakken", "itin-d3i4": "Vertrek naar Skopje", "itin-d3i5": "Aankomst in 4★-hotel in Skopje", "itin-d3i6": "Afscheidsdiner", "itin-d4n": "Dag 8", "itin-d4t": "Vertrek", "itin-d4i1": "Rustig ontbijten tot 10:00", "itin-d4i2": "Ophalen bij hotel ca. 2,5 uur voor je vlucht", "itin-d4i3": "Transfer naar de luchthaven van Skopje — goede reis!", "itin-callout-text": "Korter of langer blijven? We stellen elke reis individueel samen.", "itin-callout-btn": "Boek Je Reis", "form-name-label": "Naam", "form-email-label": "E-mail", "form-city-label": "Stad / Land", "form-guests-label": "Aantal Reizigers", "form-guests-placeholder": "Selecteer", "form-date-label": "Voorkeursdatum / -periode Reis", "form-msg-label": "Bericht (optioneel)", "form-submit-btn": "Aanvraag Versturen", "form-note-text": "We nemen binnen 24 uur contact met je op.", "form-success-msg": "&#10003; &nbsp;Bedankt! We nemen binnen 24 uur contact met je op.", "form-error-msg": "Vul alle verplichte velden in.", "partners-label": "Met Trots Ondersteund Door", "nav-why": "De Bestemming", "nav-terrain": "Terrein", "nav-pricing": "Prijzen", "nav-season": "Seizoen", "nav-book": "Nu Boeken", "footer-why": "Bestemming", "footer-terrain": "Terrein", "footer-pricing": "Prijzen", "footer-season": "Seizoen", "footer-contact": "Contact", "hero-tag": "Catskiing &amp; Catboarding &middot; &Scaron;ar Gebergte &middot; Noord-Macedo&euml;ni&euml;", "hero-title": "ONGEREPTE<br><span class=\"line2\">POEDER</span>", "hero-sub": "Geen liftrijen. Geen massamoerisme. Alleen ongerepte natuur, decennialange lokale kennis en meer dan 4.000 hoogtemeters pure Balkan-wildernis per dag, wachtend op jouw eerste spoor.", "hero-btn1": "Bekijk Pakketten", "hero-btn2": "Ontdek de Bestemming", "hero-scroll": "Scrollen", "strip1": "6 Rijdagen", "strip2": "Alleen Kleine Groepen", "strip3": "Catskiing &amp; Catboarding vanaf &euro;1.990", "strip4": "Flexibele Data", "strip5": "Europa&rsquo;s Eerste Catboarding-Operator", "why-label": "De Bestemming", "why-title": "WAAROM<br><span class=\"ice\">NOORD-MACEDO&Euml;NI&Euml;</span>", "why-body": "<p>In het <strong>&Scaron;ar Gebergte boven Popova &Scaron;apka</strong>, op 2.700 meter hoogte, runt onze partner Europa&rsquo;s allereerste catskiing &amp; catboarding operatie al sinds de vroege jaren &rsquo;90. Meer dan <strong>30 jaar lokale ervaring</strong>, opgebouwd door een team dat elke lijn, elke kom en elke verborgen sneeuwzak van deze bergen kent, en die insiderkennis zit in elke dag van jouw trip. RAW.MOUNTAIN is er elk seizoen bij sinds 2018!</p><p>Geen onderdeel van een skigebied. Puur backcountry. <strong>De sneeuwkat bereikt terrein dat geen enkel liftsysteem ooit kan bereiken.</strong> Van steile 50&deg;-kommen tot rustige bomentochten. Geen drukte, geen geprepareerde pistes, geen compromissen.</p><p><strong>Waarom RAW.MOUNTAIN de betere keuze is:</strong> vergelijkbare catski-operators in Europa rekenen &euro;2.700&ndash;3.300 voor slechts 5 dagen, vaak met grotere groepen en minder persoonlijke service. Bij ons krijg je in het weekpakket <strong>6 volle dagen catskiing &amp; catboarding vanaf &euro;1.990</strong>, all-inclusive, in kleine groepen met een toegewijde gids! &Eacute;&eacute;n extra dag alleen al rechtvaardigt het verschil. De prijs is niet lager omdat we bezuinigen, maar omdat Noord-Macedo&euml;ni&euml; simpelweg geen Chamonix of Arlberg is.</p><p>Reizen is eenvoudig: de makkelijkste verbindingen naar Skopje lopen via <strong>Z&uuml;rich, Frankfurt of Istanbul</strong>. Vanuit veel Europese steden vliegt <strong>WizzAir rechtstreeks naar Skopje</strong> voor zeer lage prijzen. Eenmaal geland regelen wij de rest.</p>", "stat1": "Tophoogte", "stat2": "Hoogtemeters / Dag", "stat3": "Jaar Lokale Operator-Ervaring", "stat4": "Jaar RAW.MOUNTAIN ter Plaatse", "terrain-label": "Wat Je Verwacht", "terrain-title": "CATSKIING &amp;<br><span class=\"ice\">CATBOARDING</span>", "t1h": "Steile Kommen", "t1p": "40&ndash;50&deg; aanhoudende hellingen met consistente sneeuwbedekking. Het soort lijn waar je jaren over napraat. We starten bovenaan en kiezen de afdaling op basis van de dagsneeuw.", "t2h": "Bomentochten", "t2p": "Strakke, speelse lijnen door oud bos. Perfect voor de middagrondes wanneer de open kommen genoeg zon hebben gehad. Beschut tegen wind, altijd goede sneeuw.", "t3h": "Couloirs", "t3p": "Natuurlijke couloirs tussen rotsformaties, van toegankelijke lijnen tot veeleisende inritten. Je gids kiest op basis van jouw niveau en de dagelijkse stabiliteit.", "t4h": "Natuurlijke Features", "t4p": "Door wind gevormde geulen, pillows en natuurlijke kickers die elke run in een creatieve sessie veranderen. Geen twee dagen zijn hetzelfde, de berg herschikt zichzelf met elke storm.", "t5h": "Poederdagen", "t5p": "Anders dan in de gecultiveerde Alpen levert deze berg echte poedercondities het hele seizoen. Als het &rsquo;s nachts sneeuwt, ben jij als eerste, geen drukte, geen uitgereden hellingen.", "t6h": "De Sneeuwkat", "t6p": "Je shuttle, je basiskamp, je verwarmde toevlucht tussen de runs. Geen liften, geen wachten. De kat brengt je naar boven, jij rijdt naar beneden, herhalen. Maximale tijd op de sneeuw.", "pricing-label": "Wat Is Inbegrepen", "pricing-title": "HET PAKKET", "price-badge": "All-Inclusive Pakket", "price-from": "vanaf", "price-per": "per persoon &middot; 6 rijdagen &middot; vanaf &euro;1.990 afhankelijk van het seizoen", "price-list": "<li><span class=\"check\">&#10003;</span>6 volle dagen catskiing &amp; catboarding</li><li><span class=\"check\">&#10003;</span>7 overnachtingen (3-sterren berghotel + 1 nacht 4-sterren hotel Skopje)</li><li><span class=\"check\">&#10003;</span>7&times; ontbijt, 6&times; diner in het hotel</li><li><span class=\"check\">&#10003;</span>Dagelijks bergse lunch &amp; snacks op de kat</li><li><span class=\"check\">&#10003;</span>Luchthaventransfer Skopje &harr; Popova &Scaron;apka</li><li><span class=\"check\">&#10003;</span>Professionele gids, 30+ jaar lokale operator-ervaring</li><li><span class=\"check\">&#10003;</span>Toegang tot wasstation &ndash; jouw board elke avond getund</li><li><span class=\"check\">&#10003;</span>Hotel SPA-toegang (zwembad, sauna)</li><li><span class=\"check\">&#10003;</span>Diner in Skopje bij vertrek</li><li><span class=\"check\">&#10003;</span>Volledige logistieke begeleiding ter plaatse</li><li><span class=\"check\">&#10003;</span>Lawinemateriaal beschikbaar op aanvraag <em>(huurvergoeding van toepassing)</em></li><li><span class=\"check\">&#10003;</span>Alle nationale parkkosten inbegrepen</li>", "not-incl": "<strong>Niet inbegrepen:</strong> Vluchten &middot; Alcoholische dranken bij het diner &middot; Massages &middot; Lawinemateriaal (LVS-pieper, schep, sonde, airbagrugzak, te huur ter plaatse)", "price-cta": "Plek Aanvragen", "cmp-title": "Waarom RAW.MOUNTAIN wint op waarde", "cmp-others": "Vergelijkbare Catski-Operators", "cmp-sub-others": "Grotere groepen &middot; Minder persoonlijk &middot; Premium alpiene prijzen", "cmp-best": "Beste Prijs-Kwaliteit", "cmp-5days": "6 dagen", "cmp-6days": "6 dagen", "cmp-sub-ours": "Kleine groepen &middot; Persoonlijk &middot; 30+ jaar lokale expertise", "cmp-callout": "<strong style=\"color:var(--accent)\">De rekensom is simpel:</strong> &euro;700&ndash;1.300 minder per persoon, kleinere groepen en een gids die deze berg door en door kent. Wij willen avontuur betaalbaar maken voor jullie!", "flex-label": "Flexibele Opties", "flex-list": "<li>&rarr; <strong style=\"color:var(--white)\">Individuele Data</strong>, kies je eigen week, eind december tot half april</li><li>&rarr; <strong style=\"color:var(--white)\">Solo of Groep</strong>, alleen, met vrienden of als crew</li><li>&rarr; <strong style=\"color:var(--white)\">Eenpersoonskamer</strong>, op aanvraag beschikbaar (kleine toeslag)</li><li>&rarr; <strong style=\"color:var(--white)\">Kortere Trips</strong>, 4&ndash;5 daagse versies mogelijk, prijs op aanvraag</li><li>&rarr; <strong style=\"color:var(--white)\">Catskiing &amp; Catboarding Gemengd</strong>, ski&euml;rs en snowboarders welkom</li>", "flights-label": "Reizen naar Skopje", "flights-body": "De makkelijkste verbindingen naar Skopje lopen via <strong style=\"color:var(--white)\">Z&uuml;rich, Frankfurt of Istanbul</strong>. Vanuit veel Europese steden vliegt <strong style=\"color:var(--white)\">WizzAir rechtstreeks naar Skopje</strong> voor zeer lage prijzen. Voor Noord-Amerikaanse rijders: vergelijkbare catskiing &amp; catboarding trips in Canada of Alaska starten vanaf $4.000&ndash;6.000 USD, v&oacute;&oacute;r transatlantische vluchten. Noord-Macedo&euml;ni&euml; biedt wereldklasse terrein voor een fractie van de kosten.", "season-label": "Wanneer Gaan", "season-title": "SEIZOEN<br><span class=\"ice\">OVERZICHT</span>", "m1": "December", "m1d": "Seizoen opent eind december. Vroeg-seizoenspoeder, minder mensen, kortere dagen. Perfect voor wie de berg voor zichzelf wil.", "m2": "Januari", "m2d": "Topconditie. Koude temperaturen zorgen voor solide sneeuwdek. Diep poeder regelmatig. Hoogseizoen voor catskiing &amp; catboarding, vroeg boeken.", "m3": "Februari", "m3d": "Het zoete punt. Maximaal sneeuwpakket, langere dagen, stabiele omstandigheden. Statistisch de beste maand voor opeenvolgende poederdagen.", "m4": "Maart", "m4d": "Anders dan in de Alpen valt er hier regelmatig verse sneeuw tot ver in maart, poedermeldingen zijn geen uitzondering maar de norm. Bluebird-ochtenden, verrassende stormseries en nog koude temperaturen zorgen voor uitzonderlijk catskiing &amp; catboarding.", "m5": "April", "m5d": "Laat je niet misleiden door de kalender. Verse sneeuw valt ook in april nog regelmatig, overdag zon, &rsquo;s nachts vers poeder. Vaak de beste rijdagen van het hele seizoen. Een verborgen parel voor laat-seizoen poederjagers.", "m6": "Op Maat", "m6d": "Jij kiest de data. Wij regelen de rest. Individuele catskiing &amp; catboarding trips zijn het hele seizoen mogelijk.", "how-label": "Het Proces", "how-title": "HOE HET<br><span class=\"ice\">WERKT</span>", "s1h": "Neem Contact Op", "s1p": "Stuur ons je gewenste data en groepsgrootte. We bevestigen beschikbaarheid en beantwoorden al je vragen.", "s2h": "Boek je Plek", "s2p": "Zeker je plek met een aanbetaling van 20% van de reissom. Wij regelen alle accommodatie, gids en sneeuwkatboekingen.", "s3h": "Boek je Vlucht", "s3p": "Vlieg naar Skopje via Z&uuml;rich, Frankfurt of Istanbul, of rechtstreeks vanuit veel Europese steden met WizzAir. We sturen je routetips zodra je geboekt hebt.", "s4h": "Aankomst &amp; Rijden", "s4p": "We halen je op op het vliegveld van Skopje. Vanaf dat moment is alles geregeld. Breng gewoon je board.", "s5h": "Beste Week van je Leven", "s5p": "6 dagen catskiing &amp; catboarding op ongerepte poeder, lekker eten, goed gezelschap en herinneringen die niet vervagen.", "faq-label": "Vragen?", "faq-grid": "<div class=\"faq-item\"><div class=\"faq-q\">Welk niveau heb ik nodig?</div><div class=\"faq-a\"><strong style=\"color:var(--accent)\">Deze trip is niet geschikt voor beginners.</strong> Je moet een ervaren wintersporter zijn met gedegen off-piste ervaring. Als je rode en zwarte pistes veilig rijdt en geen angst hebt voor diepe sneeuw, zit je perfect, je gids past het terrein altijd aan de groep aan.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Is dit alleen voor snowboarders?</div><div class=\"faq-a\">Absoluut niet. Zowel catskiing als catboarding zijn beschikbaar. Het terrein is voor ski&euml;rs en snowboarders even geschikt.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Hoe kom ik in Skopje?</div><div class=\"faq-a\">De makkelijkste verbindingen lopen via <strong>Z&uuml;rich, Frankfurt of Istanbul</strong>. Vanuit veel Europese steden vliegt <strong>WizzAir rechtstreeks naar Skopje</strong> voor zeer lage prijzen. Eenmaal geland regelen wij alles.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Moet ik lawinemateriaal meenemen?</div><div class=\"faq-a\">Je hoeft je eigen materiaal niet mee te nemen. Lawinemateriaal (LVS-pieper, schep, sonde en airbagrugzak) is ter plaatse te huur, reserveer dit bij voorkeur van tevoren. Je gids is lawinegecertificeerd.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Hoe is de accommodatie?</div><div class=\"faq-a\">Je verblijft in een solide 3-sterrenhotel in Popova &Scaron;apka met SPA-toegang (zwembad, sauna), volledig ontbijt en diner. De laatste nacht is in een 4-sterrenhotel in Skopje.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Kan ik alleen komen?</div><div class=\"faq-a\">Absoluut. Soloreizigers zijn zeer welkom. We stellen groepen samen op basis van niveau en data, zodat je altijd met gelijkgestemden rijdt.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Welk board moet ik meenemen?</div><div class=\"faq-a\">Je favoriete board is het beste board. Een poeder- of freeride-setup is ideaal. Er is een wasstation beschikbaar in het hotel elke avond, en we hebben een reserveboard met binding mee voor noodgevallen.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Wat is het boekings- en annuleringsbeleid?</div><div class=\"faq-a\">Een <strong>aanbetaling van 20%</strong> van de reissom zekert je plek. Het resterende bedrag is 30 dagen v&oacute;&oacute;r vertrek verschuldigd. Gratis annulering tot 45 dagen voor je trip. Daarna: 25% (30&ndash;45 dagen), 50% (29&ndash;15 dagen), 75% (14&ndash;7 dagen), 90% vanaf 6 dagen voor je reisdatum. We raden aan een annuleringsverzekering af te sluiten.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Heb ik een reisverzekering nodig?</div><div class=\"faq-a\">Ja, sterk aanbevolen. Je hebt een polis nodig die <strong>alpine bergreddingen en noodreddingen in alpien terrein</strong> dekt, met een minimale dekking van &euro;10.000. De meeste wintersportverzekeraars bieden dit standaard aan.</div></div><div class=\"faq-item\"><div class=\"faq-q\">Heb ik contant geld nodig?</div><div class=\"faq-a\">Het hotel accepteert creditcards, maar de meeste winkels en bars in het dorp werken alleen met contant geld. De lokale valuta is de Macedonische Denar (MKD). Geldautomaten zijn beschikbaar in de omgeving.</div></div>", "con-label": "Klaar om te Rijden?", "con-title": "LET&rsquo;S MAKE<br>IT HAPPEN", "con-body": "Plekken zijn beperkt en raken snel vol. Of je nu vragen hebt of klaar bent om je catskiing &amp; catboarding week te boeken, neem contact op en we regelen de details samen.", "con-btn1": "Stuur een Email", "con-btn2": "Bekijk Volledig Pakket", "stat1d": "Je hotel ligt op zo&rsquo;n 1.700m, wat je bijna 1.000 hoogtemeters gegarandeerd plezier geeft vanaf de deur, voordat de sneeuwkat zelfs maar begint te klimmen.", "stat2d": "4.000 hoogtemeters per dag zijn gegarandeerd, en worden regelmatig overtroffen. Dat is aanzienlijk meer dan de meeste heli-ski- of heli-boardingoperaties kunnen leveren.", "stat3d": "Onze partner ter plaatse runt catboarding al sinds de vroege jaren &rsquo;90, echte pioniers van de sport, lang voordat het elders in Europa populair werd.", "stat4d": "Bijna een decennium persoonlijke aanwezigheid op deze berg. We begeleiden onze gasten van het eerste contact tot de laatste run. Jouw maximale plezier is onze enige missie.", "trust-badge": "Europa&rsquo;s Nr. 1 Catboarding-Bestemming", "trust-headline": "VERUIT DE BESTE KEUZE VOOR<br><span class=\"ice\">CATBOARDING IN EUROPA</span>", "trust-body": "We zeggen dit niet lichtvaardig. Door de jaren heen heeft RAW.MOUNTAIN honderden riders naar het &Scaron;ar Gebergte gebracht, ski&euml;rs, snowboarders, beginners en ervaren freeriders. Elk van hen is met een glimlach op het gezicht en poeder in het hoofd naar huis gegaan. Deze berg, deze operator en dit concept zijn in Europa simpelweg in een klasse apart. Er is nergens anders op het continent waar je deze combinatie van terreinqualiteit, sneeuwkattoegang, operatorervaring en prijs-kwaliteit vindt, alles op &eacute;&eacute;n plek.", "ts1n": "100+", "ts1l": "Blije Riders &amp; meer", "ts2n": "100%", "ts2l": "Zou Terugkomen", "ts3n": "#1", "ts3l": "Beste Catboarding Prijs-Kwaliteit in Europa", "trust-cta": "Plek Vastleggen", "nav-about": "Over Mij", "footer-about": "Over mij", "about-label": "De Persoon achter RAW.MOUNTAIN", "about-title": "HEY,<br><span class=\"ice\">IK BEN FERDI</span>", "about-body": "<p>Mijn naam is Ferdi Christ en ik ben geboren in het hart van de Allg&auml;u Alpen. Snowboarden vergezelt me al meer dan 20 jaar in mijn leven &ndash; en vanaf het begin was het vooral het vrijheidsgevoel van het freeriden dat me enthousiast maakte. Diepe poederhellingen, ongerepte lijnen en het gevoel van absolute vrijheid bij elke bocht.</p><p>Jarenlang was ik actief in de snowboardindustrie en leerde ik de meest uiteenlopende bergen en freeride-bestemmingen kennen op reizen over de hele wereld. Maar na verloop van tijd werden overvolle skigebieden me gewoon te veel &ndash; ik bleef op zoek naar het echte, oorspronkelijke avontuur buiten de mainstream. Dat is precies waarom ik in Noord-Macedo&euml;ni&euml; ben blijven hangen &ndash; voor mij de perfecte belichaming van freeriden. Adembenemende bergen, ongerepte natuur, grenzeloze mogelijkheden en een van de weinige nog echt betaalbare avonturen ter wereld.</p><p>Met <strong>RAW.MOUNTAIN</strong> combineer ik mijn Duitse nauwkeurigheid ;-) en professionele organisatie met uitstekende begeleiding en de unieke Balkanvibe die je niet kunt beschrijven &ndash; die moet je zelf beleven.</p><p>Mijn team en ik staan je 24/7 ter beschikking om je een bijzondere trip te bieden &ndash; authentiek, buitengewoon en onvergetelijk.</p><p><em>Ik kijk ernaar uit je te verwelkomen bij RAW.MOUNTAIN!</em></p><div class=\"about-signature\"><span class=\"about-sig-wave\">&#128075;</span><div><div class=\"about-sig-name\">Ferdi Christ</div><div class=\"about-sig-role\">Oprichter, RAW.MOUNTAIN</div></div></div>", "about-sig-role": "Oprichter, RAW.MOUNTAIN", "con-or": "Of bereik ons direct:"
  }
} as const;

